import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Build an exact low-cost shared broadcast tree for small destination sets.

    A directed Steiner dynamic program chooses relay links that can be paid for
    once and then branched to several destinations. Reverse shortest-path
    relaxation finds the cheapest location for each shared subtree. Larger
    groups use incremental shared-edge attachment to retain scalable behavior.
    """
    import heapq

    h = G.copy()
    h.remove_edges_from(
        list(h.in_edges(src)) + list(nx.selfloop_edges(h)) +
        [(u, v) for u, v, d in h.edges(data=True) if d.get("cost") is None]
    )
    topology = BroadCastTopology(src, dsts, num_partitions)
    terminals = list(dict.fromkeys(d for d in dsts if d != src))

    # A useful relay must be reachable from the source and must be able to
    # reach at least one requested destination. Removing all other clouds
    # leaves every feasible broadcast tree unchanged while speeding up the
    # subset dynamic program.
    valid_terminals = [d for d in terminals if d in h]
    if src in h and valid_terminals:
        forward = nx.descendants(h, src) | {src}
        backward = set()
        for dst in valid_terminals:
            backward.update(nx.ancestors(h, dst))
            backward.add(dst)
        h = h.subgraph(forward & backward).copy()

    def install(edges):
        tree = nx.DiGraph()
        tree.add_edges_from(edges)
        for dst in dsts:
            if dst == src:
                route = []
            else:
                try:
                    nodes = nx.shortest_path(tree, src, dst)
                    route = [[u, v, G[u][v]] for u, v in zip(nodes, nodes[1:])]
                except nx.NetworkXNoPath:
                    nodes = nx.dijkstra_path(h, src, dst, weight="cost")
                    route = [[u, v, G[u][v]] for u, v in zip(nodes, nodes[1:])]
            for part in range(num_partitions):
                topology.set_dst_partition_paths(dst, part, list(route))

    # Exact directed-Steiner DP is inexpensive for the usual small multicast
    # groups and avoids greedy choices that prevent beneficial later sharing.
    # The cloud graphs are small enough that solving moderately larger
    # multicast groups exactly is still practical, and avoids expensive
    # greedy commitments when several destinations can share relay links.
    if len(terminals) <= 12:
        nodes = list(h)
        pos = {node: i for i, node in enumerate(nodes)}
        n, inf = len(nodes), float("inf")
        size = 1 << len(terminals)
        dp = [[inf] * n for _ in range(size)]
        choice = [[None] * n for _ in range(size)]
        incoming = {}
        for u, v, data in h.edges(data=True):
            incoming.setdefault(v, []).append((u, data["cost"]))

        for mask in range(1, size):
            if mask & (mask - 1) == 0:
                terminal = terminals[mask.bit_length() - 1]
                if terminal in pos:
                    dp[mask][pos[terminal]] = 0
                    choice[mask][pos[terminal]] = ("end",)

            sub = (mask - 1) & mask
            while sub:
                other = mask ^ sub
                if sub < other:
                    for i in range(n):
                        value = dp[sub][i] + dp[other][i]
                        if value < dp[mask][i]:
                            dp[mask][i] = value
                            choice[mask][i] = ("split", sub, other)
                sub = (sub - 1) & mask

            queue = [(dp[mask][i], node) for i, node in enumerate(nodes)
                     if dp[mask][i] < inf]
            heapq.heapify(queue)
            while queue:
                value, v = heapq.heappop(queue)
                vi = pos[v]
                if value != dp[mask][vi]:
                    continue
                for u, cost in incoming.get(v, []):
                    ui = pos[u]
                    if value + cost < dp[mask][ui]:
                        dp[mask][ui] = value + cost
                        choice[mask][ui] = ("edge", v)
                        heapq.heappush(queue, (dp[mask][ui], u))

        full = size - 1
        if not terminals:
            install([])
            return topology
        if src in pos and dp[full][pos[src]] < inf:
            edges = set()

            def expand(mask, node):
                entry = choice[mask][pos[node]]
                if entry[0] == "edge":
                    edges.add((node, entry[1]))
                    expand(mask, entry[1])
                elif entry[0] == "split":
                    expand(entry[1], node)
                    expand(entry[2], node)

            expand(full, src)
            install(edges)
            return topology

    reached, pending, edges = {src}, set(terminals), set()
    while pending:
        def marginal(u, v, data):
            return 0 if (u, v) in edges else data["cost"]

        distance, paths = nx.multi_source_dijkstra(h, reached, weight=marginal)
        candidates = [d for d in pending if d in distance]
        if not candidates:
            break
        dst = min(candidates, key=distance.get)
        path = paths[dst]
        edges.update(zip(path, path[1:]))
        reached.update(path)
        pending.difference_update(reached)

    install(edges)
    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


